class Solution {
  private long[] value, lazy;
  private java.util.HashMap<Long, Integer>[] maps;
  private int block;

  @SuppressWarnings("unchecked")
  public int[] numberOfPairs(int[] nums1, int[] nums2, int[][] queries) {
    int n = nums2.length;
    block = Math.max(1, (int) Math.sqrt(n));
    int blocks = (n + block - 1) / block;
    value = new long[n];
    lazy = new long[blocks];
    maps = new java.util.HashMap[blocks];
    for (int b = 0; b < blocks; b++) maps[b] = new java.util.HashMap<>();
    for (int i = 0; i < n; i++) {
      value[i] = nums2[i];
      maps[i / block].merge(value[i], 1, Integer::sum);
    }
    int cnt = 0;
    for (int[] q : queries) if (q[0] == 2) cnt++;
    int[] ans = new int[cnt];
    int idx = 0;
    for (int[] q : queries) {
      if (q[0] == 1) {
        int x = q[1], y = q[2], val = q[3];
        int bx = x / block, by = y / block;
        if (bx == by) {
          partial(x, y, val);
        } else {
          partial(x, (bx + 1) * block - 1, val);
          for (int b = bx + 1; b < by; b++) lazy[b] += val;
          partial(by * block, y, val);
        }
      } else {
        long total = 0;
        for (int v : nums1) {
          long want = (long) q[1] - v;
          for (int b = 0; b < blocks; b++) total += maps[b].getOrDefault(want - lazy[b], 0);
        }
        ans[idx++] = (int) total;
      }
    }
    return ans;
  }

  private void partial(int from, int to, int val) {
    for (int i = from; i <= to; i++) {
      java.util.HashMap<Long, Integer> map = maps[i / block];
      map.merge(value[i], -1, Integer::sum);
      value[i] += val;
      map.merge(value[i], 1, Integer::sum);
    }
  }
}
